'use strict';
const leagueState={best:false,tab:'guide',query:'',group:'',age:'',horizon:'age',child:'mat',compare:new Set(),opened:new Set()};
const leagueProfiles=()=>DATA.league_guide.profiles;
function leagueLink(id){const g=leagueProfiles().find(g=>g.id===id);return g?`<button class="league-link" data-guide-profile="${esc(id)}">${esc(g.name)}</button>`:''}
function leagueCategory(c){return `<div class="league-category"><h5>${esc(c.name)}</h5><dl><dt>Возраст</dt><dd>${esc(c.age)}</dd><dt>Как считается</dt><dd>${esc(c.age_rule)}</dd><dt>Команда</dt><dd>${esc(c.team)}</dd><dt>Оборудование</dt><dd>${esc(c.hardware)}</dd><dt>Вход / формат</dt><dd>${esc(c.entry)}</dd></dl>${c.note?`<p>${esc(c.note)}</p>`:''}${c.event_id?`<button class="league-link" data-open="${esc(c.event_id)}">Карточка этапа ${esc(c.event_id)} →</button>`:''}</div>`}
function leagueCard(g){const linkedThemes=[...new Set((g.event_ids||[]).flatMap(id=>EVENTS.find(e=>e.id===id)?.themes||[]))];const group=DATA.league_guide.groups[g.group];return `<article class="league-dossier" id="league-${esc(g.id)}" ${linkedThemes.length?window.STEM_DIRECTIONS.attributes(linkedThemes):''}><details data-guide-detail="${esc(g.id)}" ${leagueState.opened.has(g.id)?'open':''}><summary><div class="league-heading"><span class="league-group ${esc(g.group)}">${esc(group)}</span><span class="league-expand" aria-hidden="true">＋</span></div><h3>${esc(g.name)}</h3>${window.bestBadge('league',g.id)}${linkedThemes.length?'<span class="league-topic-note">Темы этапов в базе</span>'+window.STEM_DIRECTIONS.chips(linkedThemes):''}<p class="league-ages">${esc(g.age_summary)}</p><p>${esc(g.summary)}</p><span class="league-read">Возрастные категории, требования и путь отбора</span></summary><div class="league-details"><h4>Для чего выбирать</h4><p>${esc(g.importance)}</p><p>${esc(g.strengths)}</p><h4>Категории и возраст</h4><div class="league-categories">${g.categories.map(leagueCategory).join('')}</div><h4>Путь к следующему уровню</h4><p class="league-route-callout">${esc(g.route)}</p><h4>Требования и самостоятельность</h4><ul>${g.requirements.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h4>Нюансы перед заявкой</h4><ul>${g.nuances.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h4>Язык, бюджет и результат</h4><p><b>Язык:</b> ${esc(g.language)}</p><p>${esc(g.cost)}</p><p><b>Награды:</b> ${esc(g.award)}</p><p class="league-evidence">${esc(g.evidence)}</p><div class="league-sources">${g.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} <span>· ${esc(s.checked)}</span> ↗</a>`).join('')}</div>${g.legacy_ids.length?`<details class="league-local-details"><summary>Проверенные местные маршруты (${g.legacy_ids.length})</summary><div class="league-event-links">${g.legacy_ids.map(id=>`<button class="league-link" data-open="${esc(id)}">${esc(EVENTS.find(e=>e.id===id).title)} →</button>`).join('')}</div></details>`:''}</div></details><div class="league-card-actions"><button class="league-compare-btn ${leagueState.compare.has(g.id)?'chosen':''}" data-guide-compare="${esc(g.id)}" aria-pressed="${leagueState.compare.has(g.id)}">${leagueState.compare.has(g.id)?'✓ В сравнении':'＋ Сравнить'}</button>${g.event_ids.length?`<button class="league-link" data-league-events="${esc(g.id)}">Все этапы в базе (${g.event_ids.length}) →</button>`:'<span class="league-evidence">Календарь этапов ещё не добавлен</span>'}</div></article>`}
function renderLeagueComparison(){const a=leagueProfiles().filter(g=>leagueState.compare.has(g.id)),box=$('#league-comparison');box.hidden=!a.length;if(!a.length)return;const rows=[['Возраст','age_summary'],['Формат / особенности','summary'],['Команда','categories'],['Путь отбора','route'],['Оборудование','hardware'],['Язык','language']];box.innerHTML=`<div class="league-comparison-heading"><h3>Сравнение лиг · ${a.length} из 3</h3><button class="league-link" data-guide-clear>Очистить</button></div><div class="league-table-scroll" tabindex="0" role="region" aria-label="Сравнение выбранных лиг"><table class="league-table"><thead><tr><th scope="col">Критерий</th>${a.map(g=>`<th scope="col">${esc(g.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,key])=>`<tr><th scope="row">${label}</th>${a.map(g=>`<td>${esc(key==='categories'?[...new Set(g.categories.map(c=>c.team))].join(' / '):g[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="league-evidence">Сравнение по текущим правилам и проверенным карточкам. Самый подходящий вариант зависит от команды рядом и допуска на конкретный этап.</p>`}
function renderLeagueGuide(){window.renderKazakhstan?.();window.renderJuniorProjects?.();const guide=DATA.league_guide;$('#league-family-count').textContent=guide.profiles.length;$('#league-legacy-count').textContent=guide.legacy_count;$('#league-method').textContent=guide.methodology;$$('[data-guide-tab]').forEach(b=>{const on=b.dataset.guideTab===leagueState.tab;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});for(const id of ['guide','routes','rules'])$('#league-panel-'+id).hidden=leagueState.tab!==id;
 if(leagueState.tab==='guide'){const q=leagueState.query.trim().toLocaleLowerCase('ru');const a=leagueProfiles().filter(g=>(!leagueState.best||window.bestPickFor('league',g.id))&&(!leagueState.group||g.group===leagueState.group)&&(!leagueState.age||g.age_tags.includes(leagueState.age))&&(!q||JSON.stringify(g).toLocaleLowerCase('ru').includes(q)));$('#league-best-filter').checked=leagueState.best;$('#league-guide-search').value=leagueState.query;$('#league-group-filter').value=leagueState.group;$('#league-age-filter').value=leagueState.age;$('#league-guide-count').textContent=`${a.length} из ${guide.profiles.length} профилей лиг и программ`;$('#league-guide-cards').innerHTML=a.length?a.map(leagueCard).join(''):'<div class="league-empty"><h3>Совпадений нет</h3><p>Снимите возрастной фильтр или уточните название.</p><button class="league-link" data-guide-reset>Показать все лиги</button></div>';renderLeagueComparison();}
 if(leagueState.tab==='routes')renderDevelopmentRoutes();
 if(leagueState.tab==='rules'){$('#league-common-gates').innerHTML=guide.common_gates.map((t,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${esc(t)}</p></li>`).join('');$('#league-award-levels').innerHTML=guide.award_levels.map((x,i)=>`<article><span class="award-step">${i+1}</span><h3>${esc(x.name)}</h3><p>${esc(x.detail)}</p></article>`).join('');$('#league-legacy-list').innerHTML=DATA.leagues.map(l=>`<button class="league-legacy-item" data-open="${esc(l.id)}"><b>${esc(l.title)}</b><span>${esc(l.age)}</span><span>${esc(l.format)}</span></button>`).join('');}
}
function renderDevelopmentRoutes(){const r=DATA.development_routes,child=r.children.find(c=>c.id===leagueState.child),a=leagueState.horizon==='age'?child.stages.slice(0,3):child.stages;$$('[data-route-child]').forEach(b=>{const on=b.dataset.routeChild===leagueState.child;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});$$('[data-route-horizon]').forEach(b=>{const on=b.dataset.routeHorizon===leagueState.horizon;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});$('#route-child-intro').innerHTML=`<h3>${esc(child.name)} · сейчас ${child.age} лет</h3><p>${esc(child.intro)}</p>`;$('#route-basis').textContent=r.basis;$('#age-route-timeline').innerHTML=a.map((s,i)=>`<article class="route-stop ${esc(child.id)}"><div class="route-age"><span>${esc(s.age)}</span><small>лет</small></div><div class="route-stop-body"><span class="route-step-label">ШАГ ${i+1}</span><h3>${esc(s.title)}</h3><p>${esc(s.goal)}</p><div class="route-league-links">${s.leagues.map(leagueLink).join('')}</div><dl><dt>Что должно получиться</dt><dd>${esc(s.deliverable)}</dd><dt>Условие перехода</dt><dd>${esc(s.gate)}</dd></dl></div></article>`).join('');$('#route-first90').innerHTML=r.first90.map(s=>`<article><span class="section-kicker">${esc(s.when)}</span><h3>${esc(s.title)}</h3><ul>${s.tasks.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></article>`).join('');$('#route-practice').textContent=r.practice;$('#route-metrics').innerHTML=r.metrics.map(t=>`<li>${esc(t)}</li>`).join('');$('#route-branches').innerHTML=r.branches.map(s=>`<article><h3>${esc(s.name)}</h3><p>${esc(s.path)}</p></article>`).join('');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.guideTab){leagueState.tab=b.dataset.guideTab;renderLeagueGuide()}
 if(b.dataset.guideProfile){leagueState.tab='guide';leagueState.best=false;leagueState.query='';leagueState.group='';leagueState.age='';leagueState.opened.add(b.dataset.guideProfile);setView('leagues');renderLeagueGuide();const el=$('#league-'+b.dataset.guideProfile);el.scrollIntoView({behavior:'smooth',block:'start'});el.querySelector('summary').focus({preventScroll:true})}
 if(b.dataset.guideCompare){const id=b.dataset.guideCompare;if(leagueState.compare.has(id))leagueState.compare.delete(id);else{if(leagueState.compare.size>=3){notify('Можно сравнить до трёх лиг. Уберите одну из выбранных.');return}leagueState.compare.add(id)}renderLeagueGuide()}
 if(b.hasAttribute('data-guide-clear')){leagueState.compare.clear();renderLeagueGuide()}
 if(b.hasAttribute('data-guide-reset')){Object.assign(leagueState,{best:false,query:'',age:'',group:''});renderLeagueGuide()}
 if(b.dataset.routeChild){leagueState.child=b.dataset.routeChild;renderDevelopmentRoutes()}
 if(b.dataset.routeHorizon){leagueState.horizon=b.dataset.routeHorizon;renderDevelopmentRoutes()}
 if(b.dataset.leagueEvents){reset();state.league=b.dataset.leagueEvents;setView('catalog');$('.workspace').scrollIntoView({behavior:'smooth',block:'start'})}
});
document.addEventListener('toggle',e=>{const id=e.target.dataset?.guideDetail;if(id){if(e.target.open)leagueState.opened.add(id);else leagueState.opened.delete(id)}},true);
document.addEventListener('input',e=>{if(e.target.id==='league-guide-search'){leagueState.query=e.target.value;renderLeagueGuide()}});
document.addEventListener('change',e=>{const k={'league-group-filter':'group','league-age-filter':'age'}[e.target.id];if(k){leagueState[k]=e.target.value;renderLeagueGuide()}});
document.addEventListener('keydown',e=>{if(!e.target.matches('[data-guide-tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=$$('[data-guide-tab]'),i=tabs.indexOf(e.target),n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;leagueState.tab=tabs[n].dataset.guideTab;renderLeagueGuide();tabs[n].focus()});

document.getElementById('league-best-filter').addEventListener('change',e=>{leagueState.best=e.target.checked;renderLeagueGuide()});
